pub const DEFAULT_REMOTE_PORT: u16 = 43187;

/// Who this installation is to a remote client, and how it listens.
/// Made once on first start and kept for the life of the data
/// directory; a second data directory has its own.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Identity {
    pub schema_version: u32,
    /// Stable, random; never derived from the hostname or an address.
    pub server_id: Uuid,
    /// The display name a client shows for this host.
    pub server_name: String,
    /// The self-signed certificate, DER, base64. Public.
    pub certificate: String,
    /// SHA-256 over the certificate's `SubjectPublicKeyInfo`, hex: what
    /// a client pins, so a certificate reissued over the same key still
    /// verifies.
    pub spki_sha256: String,
    pub created: SystemTime,
    /// How the port binds.
    #[serde(default)]
    pub listen: Listen,
}

impl Identity {
    /// The Keychain account the certificate's private key is filed
    /// under: one per installation, so two data directories under one
    /// macOS account never overwrite each other's keys.
    #[must_use]
    pub fn key_account(&self) -> String {
        format!("remote-key:{}", self.server_id)
    }
}

/// Where the remote port binds. Loopback only until the owner allows
/// devices on the local network.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Listen {
    /// Bind every interface rather than loopback alone.
    pub lan: bool,
    pub port: u16,
}

impl Default for Listen {
    fn default() -> Self {
        Self {
            lan: false,
            port: DEFAULT_REMOTE_PORT,
        }
    }
}

/// What a paired device may do. Set in the host's dialog, never over
/// the port.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Scope {
    /// Every view and content read.
    Read,
    /// Reads, and the commands that put text into a session.
    Control,
}

impl Scope {
    #[must_use]
    pub fn word(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::Control => "control",
        }
    }
}

/// One device the owner paired. The bearer token itself is never
/// stored: its SHA-256 is what a request's token is checked against.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PairedDevice {
    pub id: Uuid,
    /// What the device called itself when it paired.
    pub name: String,
    pub scope: Scope,
    /// SHA-256 of the bearer token, hex.
    pub token_sha256: String,
    pub created: SystemTime,
    /// When the device last made an authenticated request.
    #[serde(default)]
    pub last_seen: Option<SystemTime>,
}

/// The two files on disk. A missing file reads as absent or empty; a
/// malformed one is an error the app reports rather than overwrites.
pub trait RemoteStore: Send {
    fn load_identity(&self) -> Result<Option<Identity>, String>;
    fn save_identity(&self, identity: &Identity) -> Result<(), String>;
    fn load_devices(&self) -> Result<Vec<PairedDevice>, String>;
    fn save_devices(&self, devices: &[PairedDevice]) -> Result<(), String>;
}

/// What the host advertises over Bonjour while it listens on the local
/// network: `_switchboard._tcp` under an instance name, with TXT records
/// a client can match against a known server before it connects. Never
/// a token, never key material: the key hash is read from `/info` over
/// the pinned connection, not from a multicast record anyone can send.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Advertisement {
    /// The Bonjour instance name: the display name with a short id
    /// suffix, so two installations on one machine stay distinct.
    pub instance: String,
    pub server_id: Uuid,
    pub server_name: String,
    pub port: u16,
/// close it early. Three tries at a 40-bit code is no odds at all, and
/// the owner sees the window close.
pub const PAIRING_WINDOW: Duration = Duration::from_mins(5);
pub const PAIRING_ATTEMPTS: u32 = 3;

/// The pairing window while it is open: the code the QR carries, what
/// a pairing made through it grants, and how many attempts failed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PairingWindow {
    pub until: Duration,
    pub code: String,
    pub scope: Scope,
    pub failures: u32,
}
/// How far back a rule set may look, in hours: an hour to a month.
pub const RULE_HOURS: std::ops::RangeInclusive<u32> = 1..=720;
/// The width, in grid units, a rule set is laid out at where no view
/// says how wide it is: the control port, and the core before the
/// first frame reports [`AppAction::ViewColumns`].
pub const RULE_COLUMNS: u32 = 24;
/// A rule set's card size in percent: small enough to fit more, never
/// so small a card's header and footer clip.
pub const RULE_SCALE: std::ops::RangeInclusive<u32> = 90..=200;

/// `hours` kept within [`RULE_HOURS`].
fn clamp_hours(hours: u32) -> u32 {
    hours.clamp(*RULE_HOURS.start(), *RULE_HOURS.end())
}

/// `scale` kept within [`RULE_SCALE`], to the nearest 10: the value a
/// rule set's scale is stored at, and the one its slider shows.
    (session, id)
}

/// One HTTP request over a fresh pinned TLS connection: the status and
/// the body.
fn http(
    addr: SocketAddr,
    config: &Arc<ClientConfig>,
    method: &str,
    path: &str,
    bearer: Option<&str>,
    body: &str,
) -> std::io::Result<(u16, String)> {
    let tcp = TcpStream::connect(addr)?;
    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
    let conn = ClientConnection::new(
        Arc::clone(config),
        ServerName::try_from("localhost").unwrap(),
    )
    .map_err(std::io::Error::other)?;
    let mut s = StreamOwned::new(conn, tcp);
    while s.conn.is_handshaking() {
        s.conn.complete_io(&mut s.sock)?;
    }
    let auth = bearer
        .map(|t| format!("Authorization: Bearer {t}\r\n"))
        .unwrap_or_default();
    write!(
        s,
        "{method} {path} HTTP/1.1\r\nHost: localhost\r\n{auth}Content-Length: {}\r\n\r\n{body}",
        body.len()
    )?;
    s.flush()?;
    let mut reader = BufReader::new(s);
    let mut line = String::new();
    reader.read_line(&mut line)?;
    let status: u16 = line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
    let mut length = 0usize;
    loop {
        let mut h = String::new();
        reader.read_line(&mut h)?;
        let h = h.trim_end();
        if h.is_empty() {
            break;
        }
        if let Some(v) = h.strip_prefix("Content-Length:") {
            length = v.trim().parse().unwrap_or(0);
        }
    }
    let mut out = vec![0; length];
    reader.read_exact(&mut out)?;
    Ok((status, String::from_utf8_lossy(&out).into_owned()))
}

/// A request from a client thread, served by the app on this thread.
fn call(
    port: &mut Port,
    method: &str,
    path: &str,
    bearer: Option<&str>,
    body: &str,
) -> (u16, serde_json::Value) {
    let addr = port.addr;
    let config = Arc::clone(&port.client);
    let (method, path, bearer, body) = (
        method.to_owned(),
        path.to_owned(),
        bearer.map(str::to_owned),
        body.to_owned(),
    );
    let client =
        std::thread::spawn(move || http(addr, &config, &method, &path, bearer.as_deref(), &body));
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    let (status, text) = client.join().unwrap().expect("http");
    let value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("{e}: {text}"));
    (status, value)
}

fn get(port: &mut Port, path: &str, bearer: Option<&str>) -> (u16, serde_json::Value) {
    call(port, "GET", path, bearer, "")
}

